    <section class="uva-card"><span class="uva-eyebrow">DAILY SETTLEMENT</span><h2>{{ $t("每日收益结算") }}</h2><p>{{ $t("静态按本金计算；V1–V9 团队级差和平级奖加速同一额度。每天只能结算一次。") }}</p><label>{{ $t("业务日期") }}<input v-model="businessDate" type="date"></label><label>{{ $t("静态日率") }}<input v-model.trim="staticRate" inputmode="decimal" placeholder="0.008–0.015"></label><button :disabled="busy || !businessDate || !staticRate" @click="send('day',{business_date:businessDate,static_rate:staticRate})">{{ $t("执行本地日结") }}</button><div class="uva-note">{{ $t("级差暂按下级当日实际静态释放计算，待业务规则最终确认。已结算日期不能修改费率重算。") }}</div></section>
