    <section class="uva-card"><span class="uva-eyebrow">MEMBER LEVEL</span><h2>{{ $t("本地测试等级") }}</h2><p>{{ $t("正式等级按当前有效业绩升降。这里可设 V4+ 测试下限以检查平级奖；选择 V0 可恢复自动等级，不影响旧 UMI。") }}</p><label>{{ $t("成员 ID") }}<input v-model.trim="levelMemberId" inputmode="numeric" :placeholder="$t(&quot;成员 ID&quot;)"></label><label>{{ $t("V 等级") }}<select v-model.number="level"><option v-for="n in 10" :key="n" :value="n-1">V{{n-1}}</option></select></label><button :disabled="busy || !levelMemberId" @click="send('level',{member_id:levelMemberId,level})">{{ $t("设置本地测试等级") }}</button></section></div>

