  <section v-if="tab==='cycles'" class="uva-card"><span class="uva-eyebrow">CYCLES & DAYS</span><h2>{{ $t("轮次与日结") }}</h2><div class="uva-table"><table><thead><tr><th>{{ $t("轮次") }}</th><th>{{ $t("成员") }}</th><th>{{ $t("本金") }}</th><th>{{ $t("倍数/额度") }}</th><th>{{ $t("已释放") }}</th><th>{{ $t("状态") }}</th></tr></thead><tbody><tr v-for="c in data.cycles" :key="c.id"><td>#{{c.id}} {{ $t("/ 第") }}{{c.cycle_number}}{{ $t("轮") }}</td><td>{{c.member_id}}</td><td>{{amount(c.principal_umi)}}</td><td>{{c.multiplier}}× / {{amount(c.cap_umi)}}</td><td>{{amount(c.released_umi)}}</td><td>{{c.status}}</td></tr></tbody></table></div><h3>{{ $t("日结记录") }}</h3><div class="uva-table"><table><thead><tr><th>{{ $t("日期") }}</th><th>{{ $t("静态率") }}</th><th>{{ $t("汇总") }}</th></tr></thead><tbody><tr v-for="d in data.days" :key="d.id"><td>{{d.business_date}}</td><td>{{amount(d.static_rate)}}</td><td>{{daySummary(d.summary_json)}}</td></tr></tbody></table></div></section>

