  <section v-if="tab==='burn'" class="uva-card"><span class="uva-eyebrow">SOURCE LOTS & BATCHES</span><h2>{{ $t("专户来源和批次") }}</h2><p>{{ $t("真实链上已确认始终为 0；模拟批次和待处理来源分开。") }}</p><div class="uva-focus">{{ $t("累计模拟销毁") }} {{amount(data.burn.simulated_confirmed_umi)}} {{ $t("UMI · 过去 24 小时") }} {{amount(data.burn.past_24h_simulated_umi)}} {{ $t("UMI · 待销毁") }} {{amount(data.burn.pending_umi)}} UMI</div><h3>{{ $t("模拟划入与充值") }}</h3><div class="uva-table"><table><thead><tr><th>{{ $t("来源编号") }}</th><th>{{ $t("来源") }}</th><th>{{ $t("轮次") }}</th><th>UMI</th><th>{{ $t("时间") }}</th></tr></thead><tbody><tr v-for="entry in data.inbounds" :key="entry.id"><td>{{entry.request_key}}</td><td>{{entry.kind==='sandbox_inbound_chain'?$t('模拟链上充值'):$t('交易所测试钱包')}}</td><td>{{entry.source_ref}}</td><td>{{amount(entry.amount_umi)}}</td><td>{{localTime(entry.created_at)}}</td></tr></tbody></table></div><h3>{{ $t("待销毁来源") }}</h3><div class="uva-table"><table><thead><tr><th>{{ $t("来源") }}</th><th>{{ $t("类型") }}</th><th>{{ $t("成员/轮次/提现") }}</th><th>UMI</th><th>{{ $t("状态") }}</th><th>{{ $t("批次") }}</th></tr></thead><tbody><tr v-for="l in data.lots" :key="l.id"><td>{{l.source_key}}</td><td>{{l.purpose}}</td><td>{{l.member_id||'—'}} / {{l.cycle_id||'—'}} / {{l.withdrawal_id||'—'}}</td><td>{{amount(l.amount_umi)}}</td><td>{{l.status}}</td><td>{{l.batch_id||'—'}}</td></tr></tbody></table></div><h3>{{ $t("模拟批次") }}</h3><div class="uva-table"><table><thead><tr><th>{{ $t("批次") }}</th><th>UMI</th><th>{{ $t("状态") }}</th><th>{{ $t("模拟凭证") }}</th><th>{{ $t("时间（北京时间）") }}</th></tr></thead><tbody><tr v-for="b in data.batches" :key="b.id"><td>#{{b.id}}</td><td>{{amount(b.amount_umi)}}</td><td>{{b.status}}</td><td>{{b.simulation_ref}}</td><td>{{localTime(b.created_at)}}</td></tr></tbody></table></div></section>
  <div v-if="tab==='settings'" class="uva-grid"><section class="uva-card"><span class="uva-eyebrow">BSC MAINNET · CHAIN ID 56</span><h2>{{ $t("链与资金池配置") }}</h2><p>{{ $t("提现付款、奖励库存来源固定为 Deepro 内部资金池。这里只保存地址草稿；真实划转、签名与销毁始终关闭。") }}</p><label>{{ $t("UMI 合约地址") }}<input v-model.trim="tokenContract" maxlength="42" :placeholder="`已登记候选：${data.chain_settings.proposed_token_contract}`"></label><label>{{ $t("BSC 黑洞地址") }}<input v-model.trim="burnAddress" maxlength="42" placeholder="0x000000000000000000000000000000000000dEaD"></label><p class="uva-note">{{ $t("BscScan 标记的常用黑洞地址：") }}{{data.chain_settings.proposed_burn_address}}{{ $t("。提交前仍须确认 UMI 合约与此地址的代币转账规则。") }}</p><label>{{ $t("专属归集账户（可暂留空）") }}<input v-model.trim="dedicatedAddress" maxlength="42" :placeholder="$t(&quot;后续由管理员填写 0x…&quot;)"></label><button :disabled="busy" @click="send('chain_settings',{token_contract:tokenContract,burn_address:burnAddress,dedicated_address:dedicatedAddress})">{{ $t("保存地址草稿") }}</button></section><section class="uva-card"><span class="uva-eyebrow">{{ $t("接入状态") }}</span><h2>{{ $t("当前配置") }}</h2><dl><div><dt>{{ $t("网络") }}</dt><dd>BSC Mainnet · 56</dd></div><div><dt>{{ $t("提现付款") }}</dt><dd>{{ $t("Deepro 资金池") }}</dd></div><div><dt>{{ $t("奖励库存") }}</dt><dd>{{ $t("Deepro 资金池") }}</dd></div><div><dt>{{ $t("合约") }}</dt><dd>{{data.chain_settings.token_contract || $t('待确认')}}</dd></div><div><dt>{{ $t("黑洞") }}</dt><dd>{{data.chain_settings.burn_address || $t('待确认')}}</dd></div><div><dt>{{ $t("专户") }}</dt><dd>{{data.chain_settings.dedicated_address || $t('未设置')}}</dd></div><div><dt>{{ $t("真实资金操作") }}</dt><dd>{{ $t("关闭") }}</dd></div></dl><h3>{{ $t("设置记录") }}</h3><div v-if="!data.chain_settings_audit.length" class="uva-note">{{ $t("暂无地址变更") }}</div><article v-for="row in data.chain_settings_audit" :key="row.id" class="uva-audit">{{ $t("管理员") }} {{row.actor_id}} · {{localTime(row.created_at)}} {{ $t("· 请求") }} {{row.request_key}}</article></section></div>
</main></admin-layout>
</template>
<script>
import UmiLocale from '@/Functions/UmiLocale';
import AdminLayout from '@/Layouts/AdminLayout';
import axios from 'axios';
export default {mixins:[UmiLocale],components:{AdminLayout},props:{state:{type:Object,required:true}},data(){return {data:this.state,tab:'operations',busy:false,error:'',message:'',pendingKey:null,memberId:'',fundAmount:'',inventoryAmount:'',inboundMemberId:'',inboundSource:'exchange',inboundAmount:'',inboundRef:'',businessDate:new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),staticRate:'0.01',levelMemberId:'',level:0,tokenContract:this.state.chain_settings?.token_contract||this.state.chain_settings?.proposed_token_contract||'',burnAddress:this.state.chain_settings?.burn_address||'',dedicatedAddress:this.state.chain_settings?.dedicated_address||'',tabs:[{id:'operations',label:this.$t("运营操作")},{id:'members',label:this.$t("成员")},{id:'cycles',label:this.$t("轮次/日结")},{id:'withdrawals',label:this.$t("提现")},{id:'burn',label:this.$t("专户/批次")},{id:'settings',label:this.$t("链与资金池")}]};},methods:{amount(v){if(v===null||v===undefined)return '0';const s=String(v);if(!/^-?\d+\.\d+$/.test(s))return s;const [whole,fraction]=s.split('.');const significant=fraction.replace(/0+$/,'');return significant?`${whole}.${significant}`:whole;},localTime(v){if(!v)return '—';const s=String(v).replace(' ','T').replace(/([+-]\d{2})$/,'$1:00');const d=new Date(s);return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(d);},daySummary(v){try{const d=typeof v==='string'?JSON.parse(v):v;return `轮次 ${d.cycles} · 释放 ${this.amount(d.released_umi)} UMI · 级差 ${d.grade_rewards||0} · 平级 ${d.peer_rewards} · 烧伤 ${this.amount(d.injured_umi)} UMI`;}catch(e){return String(v||'—');}},key(){return window.crypto&&window.crypto.randomUUID?window.crypto.randomUUID():'req-'+Date.now()+'-'+Math.floor(Math.random()*1000000);},async send(action,fields){this.error='';this.message='';this.busy=true;this.pendingKey=this.pendingKey||this.key();try{const r=await axios.post('/exchange-control-panel/umi/v2',{action,request_key:this.pendingKey,...fields});this.data=r.data.state;this.pendingKey=null;this.message='操作已记录，明细已刷新。';}catch(e){this.error=(e.response&&e.response.data&&e.response.data.message)||'操作未完成；可用原请求重试';}finally{this.busy=false;}}}};
</script>
<style scoped>
