px;border-radius:10px;background:#f5f8f6;color:#647166;margin-top:16px}.uva-focus{font-size:24px;font-weight:800;margin:20px 0}.uva-table{overflow:auto;max-width:100%}.uva table{width:100%;border-collapse:collapse;white-space:nowrap}.uva th,.uva td{text-align:left;padding:11px 12px;border-bottom:1px solid #e3eae5;font-size:13px}.uva th{color:#65746a;background:#f7faf8}.uva td button{font-size:11px;padding:6px 8px}.uva-error,.uva-ok{padding:12px 16px;border-radius:10px}.uva-error{color:#9e2424;background:#fff0ef}.uva-ok{color:#116d3c;background:#e9f8ef}@media(max-width:900px){.uva{padding:20px 14px}.uva-grid,.uva-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:580px){.uva-grid{grid-template-columns:1fr}.uva-metrics b{font-size:20px}.uva-head{align-items:start}.uva-head h1{font-size:25px}.uva-head a{font-size:12px}.uva-banner small{margin-left:0}}
.uva-card dl>div{display:flex;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px solid #e3eae5}.uva-card dt{color:#65746a}.uva-card dd{margin:0;text-align:right;overflow-wrap:anywhere;max-width:68%;font-weight:700}.uva-audit{border-top:1px solid #e3eae5;padding:10px 0;color:#65746a;font-size:12px;overflow-wrap:anywhere}
</style>
